const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
const chatwootBase = 'https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/1';

function detectLanguage(text, history = []) {
  if (!text) text = '';
  const clean = text.toLowerCase();

  const spWords = new Set(['hola','buenos','buenas','dias','tardes','noches','gracias','quiero','prueba','planes','precio','precios','cuanto','como','donde','amigo','por','favor','ayuda','cuenta','dispositivo','dispositivos','informacion','servicio','saludos','pago','tarjeta','movil','bolivares','mes','meses','ano','listo','que','cual','cuando','tengo','tienen','estoy','puedo','el','la','los','las','un','una','unos','unas','de','del','en','con','para','me','te','se','nos','gusto','mucho','excelente','bueno','bien']);
  const enWords = new Set(['hello','hi','hey','good','morning','afternoon','evening','thanks','thank','you','want','trial','plans','price','prices','how','much','where','please','help','account','device','devices','information','service','greetings','payment','card','month','months','year','ready','what','which','when','have','there','is','are','can','could','the','was','were','amazing','great','sports','channels','awesome','liked','loved','it','this','that','for','with','and','but','or','i','my','we','our']);

  const words = clean.replace(/[^a-záéíóúñ\s]/gi, ' ').split(/\s+/).filter(Boolean);
  let spCount = 0;
  let enCount = 0;
  for (const w of words) {
    if (spWords.has(w)) spCount++;
    if (enWords.has(w)) enCount++;
  }
  if (/[áéíóúñ¿¡]/.test(clean)) spCount += 2;

  if (spCount > enCount) return 'es';
  if (enCount > spCount) return 'en';

  for (let i = history.length - 1; i >= 0; i--) {
    const pClean = (history[i] || '').toLowerCase();
    const pWords = pClean.replace(/[^a-záéíóúñ\s]/gi, ' ').split(/\s+/).filter(Boolean);
    let pSp = 0, pEn = 0;
    for (const w of pWords) {
      if (spWords.has(w)) pSp++;
      if (enWords.has(w)) pEn++;
    }
    if (/[áéíóúñ¿¡]/.test(pClean)) pSp += 2;
    if (pSp > pEn) return 'es';
    if (pEn > pSp) return 'en';
  }

  return 'es';
}

const results = [];
const now = Date.now();

// Fetch all open conversations (supporting pagination)
let allOpenConvs = [];
try {
  let page = 1;
  while (page <= 5) {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: `${chatwootBase}/conversations?status=open&page=${page}`,
      headers: { 'api_access_token': chatwootToken },
      json: true
    });
    const payload = resp.data?.payload || [];
    if (payload.length === 0) break;
    allOpenConvs.push(...payload);
    if (payload.length < 25) break;
    page++;
  }
} catch (e) {}

// Deduplicate conversations by ID
const convMap = new Map();
for (const c of allOpenConvs) {
  if (c && c.id) convMap.set(c.id, c);
}

for (const [convId, conv] of convMap.entries()) {
  const currentLabels = Array.isArray(conv.labels) ? conv.labels : [];
  const customAttrs = conv.custom_attributes || {};
  const inboxId = Number(conv.inbox_id || 0);

  // 1. Safety check: Ignore human agent or terminal stage conversations
  if (currentLabels.includes('human') || currentLabels.includes('stage-leads-ganados') || currentLabels.includes('stage-leads-perdidos')) {
    continue;
  }

  // 2. Identify brand
  const isTVTotal24 = (inboxId === 10 || inboxId === 13 || inboxId === 15 || inboxId === 16 || inboxId === 19 || currentLabels.includes('funnel-totaltv-latina') || currentLabels.includes('funnel-total-tv-latina'));
  const brand = isTVTotal24 ? 'tvtotal24' : 'totaltvusa';

  // 3. Check stage: must be incoming leads stage or unassigned
  const hasIncomingStage = currentLabels.includes('stage-lead-entrantes') || currentLabels.includes('stage-leads-entrantes') || currentLabels.includes('stage-incoming-leads');
  const hasAnyOtherStage = currentLabels.some(l => l.startsWith('stage-') && !['stage-lead-entrantes', 'stage-leads-entrantes', 'stage-incoming-leads'].includes(l));

  if (hasAnyOtherStage) {
    continue;
  }

  // 4. Check if already followed up
  if (customAttrs.stage_contacted_followup_at || customAttrs.stage_contactado_followup_at) {
    continue;
  }

  // 5. Fetch messages
  let msgs = [];
  try {
    const msgResp = await this.helpers.httpRequest({
      method: 'GET',
      url: `${chatwootBase}/conversations/${convId}/messages`,
      headers: { 'api_access_token': chatwootToken },
      json: true
    });
    msgs = msgResp.payload || [];
  } catch (e) {
    continue;
  }

  const customerMsgs = msgs.filter(m => (m.message_type === 0 || m.message_type === 'incoming') && m.private !== true);

  let lastCustomerTimeMs = 0;
  let lastCustomerContent = '';
  const customerHistory = [];

  if (customerMsgs.length > 0) {
    const lastMsg = customerMsgs[customerMsgs.length - 1];
    lastCustomerTimeMs = (lastMsg.created_at || lastMsg.created_at_epoch) * 1000;
    lastCustomerContent = lastMsg.content || '';
    for (const m of customerMsgs) {
      if (m.content) customerHistory.push(m.content);
    }
  } else {
    lastCustomerTimeMs = (conv.created_at || conv.last_activity_at) * 1000;
  }

  const elapsedHours = (now - lastCustomerTimeMs) / (1000 * 3600);

  if (elapsedHours >= 20) {
    const targetStageAdd = isTVTotal24 ? 'stage-contactado' : 'stage-contacted';
    const lang = detectLanguage(lastCustomerContent, customerHistory);
    let followUpText = '';

    if (isTVTotal24) {
      if (lang === 'en') {
        followUpText = 'Hello! 👋 It was a pleasure assisting you at **TVTotal24**. We remain at your disposal for any further questions or whenever you wish to test or activate our service. Have a wonderful day! 😊';
      } else {
        followUpText = '¡Hola! 👋 Ha sido un verdadero gusto atenderte en **TVTotal24**. Quedamos a tu entera disposición para cualquier consulta o cuando desees probar o activar el servicio. ¡Que tengas un excelente día! 😊';
      }
    } else {
      if (lang === 'en') {
        followUpText = 'Hello! 👋 It was a pleasure assisting you at **TotalTv**. We remain at your disposal for any further questions or whenever you wish to test or activate our service. Have a great day! 😊';
      } else {
        followUpText = '¡Hola! 👋 Ha sido un gusto atenderte en **TotalTv**. Quedamos a tu entera disposición para nuevas consultas o cuando desees probar o activar tu servicio. ¡Que tengas un excelente día! 😊';
      }
    }

    // Format for Meta channels (WhatsApp / Instagram / Facebook)
    if (inboxId === 16 || inboxId === 19 || inboxId === 13 || inboxId === 14 || inboxId === 17 || inboxId === 18 || inboxId === 4) {
      followUpText = followUpText.replace(/\*\*(.*?)\*\*/g, '*$1*');
      followUpText = followUpText.replace(/\[(.*?)\]\((.*?)\)/g, '$1: $2');
    }

    // Clean prior stage labels and assign target stage
    const updatedLabels = currentLabels.filter(l => !l.startsWith('stage-'));
    updatedLabels.push(targetStageAdd);

    // Update labels
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${chatwootBase}/conversations/${convId}/labels`,
        headers: {
          'api_access_token': chatwootToken,
          'Content-Type': 'application/json'
        },
        body: { labels: updatedLabels },
        json: true
      });
    } catch (e) {}

    // Send outgoing message
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${chatwootBase}/conversations/${convId}/messages`,
        headers: {
          'api_access_token': chatwootToken,
          'Content-Type': 'application/json'
        },
        body: {
          content: followUpText,
          message_type: 'outgoing',
          private: false
        },
        json: true
      });
    } catch (e) {}

    // Mark custom attribute MERGED with existing attributes
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${chatwootBase}/conversations/${convId}/custom_attributes`,
        headers: {
          'api_access_token': chatwootToken,
          'Content-Type': 'application/json'
        },
        body: {
          custom_attributes: {
            ...customAttrs,
            stage_contacted_followup_at: new Date().toISOString()
          }
        },
        json: true
      });
    } catch (e) {}

    results.push({
      convId,
      brand,
      action: 'transitioned_and_sent',
      newStage: targetStageAdd,
      elapsedHours: Math.round(elapsedHours * 10) / 10,
      language: lang
    });
  } else {
    results.push({
      convId,
      brand,
      action: 'waiting',
      elapsedHours: Math.round(elapsedHours * 10) / 10,
      neededHours: 20
    });
  }
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    processed_count: results.length,
    results
  }
}];

